import { readFileSync } from 'node:fs';

export interface Settings {
  currency: string;
  locale: string;
  roundTo: number;
}

const CURRENCY = /^[A-Z]{3}$/;

export function readSettings(path = 'invoice.config.json'): Settings {
  const raw = JSON.parse(readFileSync(path, 'utf8'));
  if (!CURRENCY.test(raw.currency)) {
    throw new Error(`Invalid currency code: ${raw.currency}`);
  }
  return { currency: raw.currency, locale: raw.locale ?? 'en-US', roundTo: raw.roundTo ?? 2 };
}

import { writeFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { loadSettings, type Settings } from '../config';
import { formatInvoice, type Invoice } from '../format';

function resolveTarget(dir: string, id: string): string {
  mkdirSync(dir, { recursive: true });
  return join(dir, `${id}.txt`);
}

export function exportInvoice(invoice: Invoice, settings?: Settings): string {
  const active = settings ?? loadSettings();
  const body = formatInvoice(invoice, active);
  if (!body.trim()) {
    throw new Error(`Invoice ${invoice.id} rendered empty`);
  }

  const target = resolveTarget(process.env.EXPORT_DIR, invoice.id);
  writeFileSync(target, body);
  return target;
}

import type { Settings } from './config.js';

export interface Invoice {
  id: string;
  customer: string;
  lines: Array<{ description: string; quantity: number; unitPrice: number }>;
}

export function formatInvoice(invoice: Invoice, settings: Settings): string {
  const money = new Intl.NumberFormat(settings.locale, { style: 'currency', currency: settings.currency });
  const rows = invoice.lines.map(line => `${line.description}  x${line.quantity}  ${money.format(line.quantity * line.unitPrice)}`);
  const total = invoice.lines.reduce((sum, line) => sum + line.quantity * line.unitPrice, 0);
  return [`Invoice ${invoice.id} for ${invoice.customer}`, ...rows, `Total ${money.format(total)}`].join('\n');
}
